//! 🧠️ Original evaluation reply custody reaches native Dictionary binding and paid cache transfer.
use super::*;
use semio_framework_job::{StepContext,OriginalTurnFailure,InteractiveJobCloseStep};
use semio_framework_value::{DslValue,Number};
use protocol::causal::transition::HistoryFoldIndexInsert;
use std::mem::{ManuallyDrop,size_of};
const KEYS:[&str;6]=["done","cancellable","phase","unitsDone","unitsTotal","output"];
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
fn admitted(d:RetirementDemand,g:RetainedCloneGrant)->bool{g.maximum_items!=0&&d.copy_bytes<=g.maximum_copy_bytes&&d.capacity_bytes<=g.maximum_capacity_bytes&&d.release_bytes<=g.maximum_release_bytes&&d.depth<=g.maximum_depth}
fn rows(source:&DslValue)->Result<&[(String,DslValue)],ValueError>{match source{DslValue::Object(rows)=>Ok(rows),_=>Err(invalid("original evaluation reply requires an object"))}}
fn rows_mut(source:&mut DslValue)->Result<&mut[(String,DslValue)],ValueError>{match source{DslValue::Object(rows)=>Ok(rows),_=>Err(invalid("original evaluation reply requires an object"))}}
fn number_demand(_: &u64,_:&u64,_:usize,_:usize)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:2*size_of::<u64>(),depth:1,..Default::default()})}
fn number_step(left:&u64,right:&u64,_:usize,g:RetainedCloneGrant)->Result<(Option<std::cmp::Ordering>,usize,RetainedCloneProgress),ValueError>{if g.maximum_copy_bytes<2*size_of::<u64>(){return Ok((None,0,Default::default()))}Ok((Some(left.cmp(right)),0,RetainedCloneProgress{copied_items:1,copied_bytes:2*size_of::<u64>(),..Default::default()}))}
#[derive(semio_framework_value::RetireOwned)]
struct Fields{source:Option<DslValue>,dictionary:Option<Dictionary>,insertion:Option<HistoryFoldIndexInsert<u64,PreviewEvalProgress>>,displaced:Option<ControlledRetirement<(u64,PreviewEvalProgress)>>}
/// 🪪️ This exact command metadata stays borrowed throughout receiving and cache publication.
pub struct FlowEvaluationReplyAddress<'a>{pub node_hash:u64,pub window_id:&'a str,pub window_kind_id:&'a str}
impl FlowEvaluationReplyAddress<'_>{fn binding(&self)->[u64;5]{[self.node_hash,self.window_id.as_ptr()as u64,self.window_id.len()as u64,self.window_kind_id.as_ptr()as u64,self.window_kind_id.len()as u64]}}
/// 🧳️ Original intake failures preserve the exact source or fully constructed receiving owner.
pub enum FlowEvaluationReplyIntakeSource{Value(DslValue),Receiver(FlowEvaluationReplyReceiver)}
/// 🧵️ No evaluation output is reconstructed from serialized text or cold cache seeding.
pub struct FlowEvaluationReplyReceiver{origin:(u64,u64),binding:Option<[u64;5]>,fields:ManuallyDrop<Option<Fields>>,decoder:Option<neural::retirement::RetainedDictionaryInput>,cache:Option<neural::NeuralCacheInsert>,source_close:Option<ControlledRetirement<DslValue>>,close:Option<ControlledRetirement<Fields>>,scan:usize,field:Option<usize>,slots:[usize;6],phase:u8,ledger_slot:usize,done:bool,cancellable:bool,progress:PreviewEvalProgress,closing:bool,received:bool}
impl FlowEvaluationReplyReceiver{
 pub fn new(source:DslValue,cx:&mut StepContext<'_>)->Result<Self,(OriginalTurnFailure,FlowEvaluationReplyIntakeSource)>{
  if cx.is_cancelled()||cx.should_yield()||cx.retained_grant().maximum_items==0||cx.retained_grant().maximum_depth==0{return Err((invalid("original evaluation reply intake awaits admission").into(),FlowEvaluationReplyIntakeSource::Value(source)))}cx.consume_fuel(1);if rows(&source).is_err()||rows(&source).unwrap().len()!=6{return Err((invalid("original evaluation reply member shape is invalid").into(),FlowEvaluationReplyIntakeSource::Value(source)))}
  let receiver=Self{origin:(cx.operation().0,cx.generation().0),binding:None,fields:ManuallyDrop::new(Some(Fields{source:Some(source),dictionary:None,insertion:None,displaced:None})),decoder:None,cache:None,source_close:None,close:None,scan:0,field:None,slots:[usize::MAX;6],phase:0,ledger_slot:0,done:false,cancellable:false,progress:Default::default(),closing:false,received:false};if let Err(error)=cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()}){return Err((error.into(),FlowEvaluationReplyIntakeSource::Receiver(receiver)))}Ok(receiver)
 }
 pub fn next_demands(&self,session:&FlowEvalSession,body:usize,window:&str)->Result<RetirementDemand,ValueError>{
  if self.closing{return self.next_close_demands(body)}if self.terminal_is_empty(){return Ok(Default::default())}let fields=self.fields.as_ref().unwrap();if let Some(close)=fields.displaced.as_ref(){return close.selected_demand(body)}
  Ok(match self.phase{
   0=>{let source=rows(fields.source.as_ref().unwrap())?;RetirementDemand{copy_bytes:match self.field{None=>source.get(self.scan).map_or(0,|(key,_)|key.len().min(11)),Some(0|1)=>size_of::<bool>(),Some(2)=>match &source[self.scan].1{DslValue::String(value)=>value.len().min(64),_=>0},Some(3|4)=>size_of::<Number>()+size_of::<u64>(),_=>0},depth:1,..Default::default()}},
   2=>{let owner=self.decoder.as_ref().unwrap();RetirementDemand{copy_bytes:owner.next_copy_byte_demand()?,capacity_bytes:owner.next_capacity_byte_demand(body)?,release_bytes:owner.next_release_byte_demand()?,depth:owner.next_depth_demand()?}},
   3=>{let owner=self.decoder.as_ref().unwrap();RetirementDemand{copy_bytes:owner.next_close_copy_byte_demand()?,capacity_bytes:owner.next_close_capacity_byte_demand(body)?,release_bytes:owner.next_close_release_byte_demand()?,depth:owner.next_close_depth_demand()?}},
   5=>self.cache.as_ref().unwrap().next_demands(session.neural_cache.as_deref().ok_or_else(||invalid("original evaluation reply cache is absent"))?,body)?,
   8=>self.source_close.as_ref().unwrap().selected_demand(body)?,
   9 if self.done=>RetirementDemand{copy_bytes:if self.ledger_slot<session.eval_progress_by_hash.slot_count(){2*size_of::<u64>()}else{0},depth:if self.ledger_slot<session.eval_progress_by_hash.slot_count(){session.eval_progress_by_hash.next_extract_slot_depth_demand(self.ledger_slot)?.max(1)}else{1},..Default::default()},
   10|11=>fields.insertion.as_ref().unwrap().next_demands(&session.eval_progress_by_hash,body,number_demand)?,
   12=>RetirementDemand{copy_bytes:window.len(),depth:1,..Default::default()},
   _=>RetirementDemand{depth:1,..Default::default()},
  })
 }
 pub fn step(&mut self,session:&mut FlowEvalSession,address:&FlowEvaluationReplyAddress<'_>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  if self.terminal_is_empty(){return Ok(self.received)}if self.closing{return Err(invalid("original evaluation reply is closing").into())}if cx.is_cancelled()||cx.should_yield(){return Ok(false)}let g=cx.retained_grant();let d=self.next_demands(session,g.maximum_copy_bytes,address.window_id)?;if !admitted(d,g){return Ok(false)}if self.origin!=(cx.operation().0,cx.generation().0)||self.binding.is_some_and(|binding|binding!=address.binding()){cx.consume_fuel(1);return Err(invalid("original evaluation reply initiating source changed").into())}self.binding=Some(address.binding());
  if let Some(close)=self.fields.as_mut().unwrap().displaced.as_mut(){semio_framework_job::close_original_retained_step(cx,d,|g|close.step(g))?;if close.terminal_is_empty(){self.fields.as_mut().unwrap().displaced=None;}return Ok(false)}
  match self.phase{
   2=>{cx.consume_fuel(1);match self.decoder.as_mut().unwrap().step(RetainedCloneGrant{maximum_items:1,..g}){Ok(step)=>{if let Some(dictionary)=step.dictionary{self.fields.as_mut().unwrap().dictionary=Some(dictionary);self.decoder.as_mut().unwrap().cancel();self.phase=3;}cx.consume_retained(step.progress)?},Err(error)=>return Err(OriginalTurnFailure::debit_original(error,cx))}return Ok(false)},
   3=>{semio_framework_job::close_original_retained_step(cx,d,|g|self.decoder.as_mut().unwrap().close_step(g))?;if self.decoder.as_ref().unwrap().terminal_is_empty(){self.decoder=None;self.phase=4;}return Ok(false)},
   4=>{let dictionary=self.fields.as_mut().unwrap().dictionary.take().unwrap();match neural::NeuralCacheInsert::new(session.neural_cache.as_deref().ok_or_else(||invalid("original evaluation reply cache is absent"))?,address.node_hash,dictionary,cx){Ok(cache)=>{self.cache=cache;self.phase=5;},Err((error,dictionary))=>{self.fields.as_mut().unwrap().dictionary=Some(dictionary);return Err(error)}}return Ok(false)},
   5=>{if self.cache.as_mut().unwrap().step(session.neural_cache.as_deref().ok_or_else(||invalid("original evaluation reply cache is absent"))?,cx)?{self.cache=None;self.phase=7;}return Ok(false)},
   8=>{semio_framework_job::close_original_retained_step(cx,d,|g|self.source_close.as_mut().unwrap().step(g))?;if self.source_close.as_ref().unwrap().terminal_is_empty(){self.source_close=None;self.phase=9;}return Ok(false)},_=>{},
  }
  cx.consume_fuel(1);let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};let result=(||->Result<(),ValueError>{match self.phase{
   0=>{let source=rows(self.fields.as_ref().unwrap().source.as_ref().unwrap())?;if self.scan==source.len(){if self.slots.contains(&usize::MAX)||self.progress.units_done>self.progress.units_total||self.cancellable==self.done{return Err(invalid("original evaluation reply completion is inconsistent"))}if self.done&&!matches!(self.progress.phase,PreviewEvalPhase::Complete|PreviewEvalPhase::Cancelled){return Err(invalid("original evaluation reply terminal phase is invalid"))}if !self.done&&matches!(self.progress.phase,PreviewEvalPhase::Complete|PreviewEvalPhase::Cancelled){return Err(invalid("original evaluation reply partial phase is invalid"))}if self.done&&matches!(self.progress.phase,PreviewEvalPhase::Complete)&&self.progress.units_done!=self.progress.units_total{return Err(invalid("original evaluation reply completed units differ"))}self.phase=if self.done&&self.progress.phase==PreviewEvalPhase::Complete{1}else{7};return Ok(())}let(key,value)=&source[self.scan];let Some(field)=self.field else{if key.len()>11{return Err(invalid("original evaluation reply member is unknown"))}let field=KEYS.iter().position(|candidate|*candidate==key).ok_or_else(||invalid("original evaluation reply member is unknown"))?;if self.slots[field]!=usize::MAX{return Err(invalid("original evaluation reply member is duplicated"))}self.slots[field]=self.scan;self.field=Some(field);return Ok(())};match field{0=>{let DslValue::Bool(value)=value else{return Err(invalid("original evaluation done flag is absent"))};self.done=*value;},1=>{let DslValue::Bool(value)=value else{return Err(invalid("original evaluation cancellable flag is absent"))};self.cancellable=*value;},2=>{let DslValue::String(value)=value else{return Err(invalid("original evaluation phase is absent"))};if value.is_empty()||value.len()>64{return Err(invalid("original evaluation phase extent is invalid"))}self.progress.phase=PreviewEvalPhase::from_job_tag(value);},3|4=>{let DslValue::Number(value)=value else{return Err(invalid("original evaluation units are absent"))};let value=value.as_u64().ok_or_else(||invalid("original evaluation units require UInt64"))?;if field==3{self.progress.units_done=value;}else{self.progress.units_total=value;}},5=>{},_=>unreachable!()}self.field=None;self.scan+=1;},
   1=>{let fields=self.fields.as_mut().unwrap();let source=&mut rows_mut(fields.source.as_mut().unwrap())?[self.slots[5]].1;if !matches!(source,DslValue::Object(_)){return Err(invalid("original completed evaluation requires a typed Dictionary"))}self.decoder=Some(neural::retirement::RetainedDictionaryInput::new(std::mem::replace(source,DslValue::Null)));self.phase=2;},
   7=>{if !self.done||self.progress.phase==PreviewEvalPhase::Cancelled{if !matches!(rows(self.fields.as_ref().unwrap().source.as_ref().unwrap())?[self.slots[5]].1,DslValue::Null){return Err(invalid("original unfinished evaluation cannot carry a typed output"))}}self.source_close=Some(ControlledRetirement::new(self.fields.as_mut().unwrap().source.take().unwrap()).unwrap_or_else(|_|unreachable!()));self.phase=8;},
   9=>{if !self.done{self.fields.as_mut().unwrap().insertion=Some(HistoryFoldIndexInsert::new(address.node_hash,self.progress));self.phase=10;}else if self.ledger_slot==session.eval_progress_by_hash.slot_count(){self.phase=12;}else{if session.eval_progress_by_hash.slot_entry(self.ledger_slot).is_some_and(|(hash,_)|*hash==address.node_hash){let original=session.eval_progress_by_hash.extract_slot_if(self.ledger_slot,|_,_|false).unwrap();self.fields.as_mut().unwrap().displaced=Some(ControlledRetirement::new(original).unwrap_or_else(|_|unreachable!()));}self.ledger_slot+=1;}},
   10=>{let(ready,physical)=self.fields.as_mut().unwrap().insertion.as_mut().unwrap().step(&mut session.state.eval_progress_by_hash,RetainedCloneGrant{maximum_items:1,..g},number_step)?;p=physical;if ready{self.phase=11;}},
   11=>{let(slot,original,physical)=self.fields.as_mut().unwrap().insertion.as_mut().unwrap().commit_or_replace_with(&mut session.state.eval_progress_by_hash,RetainedCloneGrant{maximum_items:1,..g},|progress|progress)?;p=physical;if slot.is_some(){self.fields.as_mut().unwrap().insertion=None;if let Some(original)=original{self.fields.as_mut().unwrap().displaced=Some(ControlledRetirement::new(original).unwrap_or_else(|_|unreachable!()));}self.phase=12;}},
   12=>{let(_,physical)=session.settle_window_extension(address.window_id,RetainedCloneGrant{maximum_items:1,..g})?;p=physical;p.copied_bytes=p.copied_bytes.checked_add(d.copy_bytes).ok_or_else(||invalid("original evaluation settlement copy extent overflows"))?;self.fields.take();self.received=true;},_=>return Err(invalid("original evaluation receiving phase is invalid")),}Ok(())})();match result{Ok(())=>cx.consume_retained(p)?,Err(error)=>return Err(OriginalTurnFailure::debit_original(if error.retained_progress()==Default::default(){error.with_retained_progress(p)}else{error},cx))}Ok(self.received)
 }
 pub fn begin_close(&mut self){self.closing=true;if let Some(decoder)=self.decoder.as_mut(){decoder.cancel()}if let Some(cache)=self.cache.as_mut(){cache.begin_close()}}
 pub fn next_close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(decoder)=self.decoder.as_ref(){return Ok(RetirementDemand{copy_bytes:decoder.next_close_copy_byte_demand()?,capacity_bytes:decoder.next_close_capacity_byte_demand(body)?,release_bytes:decoder.next_close_release_byte_demand()?,depth:decoder.next_close_depth_demand()?})}if let Some(cache)=self.cache.as_ref(){return cache.next_close_demands(body)}if let Some(close)=self.source_close.as_ref(){return close.selected_demand(body)}self.close.as_ref().map_or(Ok(RetirementDemand{depth:usize::from(self.fields.is_some()),..Default::default()}),|close|close.selected_demand(body))}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{
  self.begin_close();if self.terminal_is_empty(){return Ok(InteractiveJobCloseStep::Complete{progress:Default::default()})}if self.origin!=(cx.operation().0,cx.generation().0){if cx.should_yield(){return Ok(InteractiveJobCloseStep::Blocked)}cx.consume_fuel(1);return Err(invalid("original evaluation close initiating source changed").into())}let d=self.next_close_demands(cx.retained_grant().maximum_copy_bytes)?;
  if let Some(cache)=self.cache.as_mut(){let step=cache.close_step(cx)?;if cache.terminal_is_empty(){self.cache=None;}return Ok(InteractiveJobCloseStep::Pending{progress:step.progress()})}
  let step=semio_framework_job::close_original_retained_step(cx,d,|g|if let Some(decoder)=self.decoder.as_mut(){decoder.close_step(g)}else if let Some(close)=self.source_close.as_mut(){close.step(g)}else if let Some(close)=self.close.as_mut(){close.step(g)}else{self.close=Some(ControlledRetirement::new(self.fields.take().unwrap()).unwrap_or_else(|_|unreachable!()));Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..Default::default()}))})?;
  if self.decoder.as_ref().is_some_and(|decoder|decoder.terminal_is_empty()){self.decoder=None;}if self.source_close.as_ref().is_some_and(|close|close.terminal_is_empty()){self.source_close=None;}if self.close.as_ref().is_some_and(|close|close.terminal_is_empty()){self.close=None;}Ok(if self.terminal_is_empty(){InteractiveJobCloseStep::Complete{progress:step.progress()}}else{InteractiveJobCloseStep::Pending{progress:step.progress()}})
 }
 pub fn terminal_is_empty(&self)->bool{self.fields.is_none()&&self.decoder.is_none()&&self.cache.is_none()&&self.source_close.is_none()&&self.close.is_none()}
}
impl Drop for FlowEvaluationReplyReceiver{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original evaluation reply requires paid full close");}}

